INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('energieunabhaengigkeit-oesterreich-kompass-fossile-importe','Energieunabhängigkeit Österreich: 10 Mrd. Euro jährlich für Öl und Gas','Rund 59 Prozent der Energie kommen aus dem Ausland, jährlich fließen etwa 10 Milliarden Euro für fossile Importe ab. Ein neuer Online-Kompass bündelt die Zahlen.','Bei der **Energieunabhängigkeit Österreich** zeigt eine neue Datenplattform, wie groß die Lücke noch ist: Rund 59 Prozent der im Land verbrauchten Energie stammen aus dem Ausland. Das ist eine der Kernaussagen des „Kompass Energieunabhängigkeit“, den der Branchenverband Oesterreichs Energie gemeinsam mit der Österreichischen Energieagentur am Donnerstag in Wien vorgestellt hat.

Die Plattform ist online unter oesterreichsenergie.at/kompass frei zugänglich. Sie soll Politik, Wirtschaft, Medien und Öffentlichkeit eine gemeinsame Zahlenbasis bieten: wie viel Energie Österreich selbst erzeugt, woher die Importe kommen, welche Kosten und Risiken damit verbunden sind und welche Rolle Speicher spielen.

## Rund 10 Milliarden Euro pro Jahr für fossile Importe

Laut den Daten fließen im Schnitt der vergangenen zehn Jahre jährlich rund 10 Milliarden Euro netto für Öl, Gas und Kohle ins Ausland. Dazu kommen nach Angaben der Initiatoren weitere Belastungen, etwa für strategische Reserven, Krisenhilfen und schwer kalkulierbare Preissprünge.

Verbandspräsident Michael Baminger stellte die Summe einem anschaulichen Vergleich gegenüber: Mit diesem Betrag ließen sich etwa 1.000 Windräder bauen. Damit wären die Ausbauziele für Windkraft bis 2040 seiner Einschätzung nach schon in rund zwei Jahren erreichbar.

Die Abhängigkeit ist je nach Energieträger unterschiedlich stark:

- **Erdöl:** 96 Prozent kommen aus dem Ausland, Rohöl gelangt fast ausschließlich über die Transalpine Ölleitung und die Adria-Wien-Pipeline ins Land. 2024 stammten 55 Prozent der Rohölimporte aus Kasachstan.
- **Erdgas:** 93 Prozent werden importiert, seit 2025 vor allem über Deutschland und Italien.
- **Kohle:** Sie wird zur Gänze eingeführt.

## Was Österreich selbst erzeugt

Die heimische Energieerzeugung lag 2025 bei rund 155 Terawattstunden (TWh). Den größten Anteil – knapp die Hälfte – liefert mit etwa 75 TWh die Bioenergie, also vor allem Holz und Biomasse. Die Wasserkraft steuert rund 33 TWh bei, weitere Beiträge kommen aus Photovoltaik, Windkraft und Umgebungswärme, etwa über Wärmepumpen. Heimisches Öl und Gas spielen nur eine untergeordnete Rolle.

Beim Strom zeigt der Kompass eine wichtige Einschränkung: Über das Jahr betrachtet reicht der in Österreich erzeugte erneuerbare Strom nur in ungefähr jeder fünften Stunde aus, um den gesamten Bedarf zu decken. In den übrigen Stunden braucht es Importe oder fossile Kraftwerke.

## Speicher als Schlüssel zur Energieunabhängigkeit

Einen eigenen Schwerpunkt legt die Plattform auf Speicher:

1. **Gasspeicher:** Die Kapazität liegt bei rund 100 TWh, das entspricht etwa 80 Prozent des jährlichen Gasverbrauchs. Im Oktober waren die Speicher zu rund 69 Prozent gefüllt. Ein beträchtlicher Teil gehört allerdings ausländischen Kunden.
2. **Pumpspeicher und Speicherseen:** Sie fassen rund 3,3 TWh – rechnerisch genug für etwa 18 Tage Stromverbrauch.
3. **Batteriespeicher:** Die installierte Kapazität wird auf etwa 3 bis 4 Gigawattstunden geschätzt.

## Forderungen der E-Wirtschaft

Baminger betonte, Unabhängigkeit bedeute keine Abschottung – der europäische Strommarkt bleibe unverzichtbar. Ziel sei, Öl- und Gasimporte schrittweise durch heimischen erneuerbaren Strom zu ersetzen. Dafür brauche es den Ausbau von Netzen und Speichern, die Umstellung fossiler Anwendungen auf Strom sowie klare Regeln und raschere Genehmigungsverfahren.

Generalsekretärin Barbara Schmidt verwies auf die Abhängigkeit von Weltmarktpreisen und geopolitischen Krisen. Christoph Dolna-Gruber von der Energieagentur argumentierte, dass heimische erneuerbare Energie neben der Versorgungssicherheit auch Wertschöpfung im Inland und die wirtschaftliche Widerstandskraft stärke.

## Was das für Haushalte bedeutet

Für private Haushalte ist der Kompass vor allem eine Orientierungshilfe: Er macht sichtbar, warum Preisschocks bei Öl und Gas direkt auf Heiz- und Energiekosten durchschlagen. Wer über einen Heizungstausch, eine Photovoltaikanlage oder einen Stromspeicher nachdenkt, findet dort den größeren Zusammenhang – konkrete Förderinformationen bietet die Plattform jedoch nicht. Dafür bleiben die Förderstellen von Bund und Ländern die richtige Anlaufstelle.','energie','Klima',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/energieunabhaengigkeit-oesterreich-kompass-fossile-importe.webp','Oesterreichs Energie / Österreichische Energieagentur (APA-OTS)','https://www.ots.at/presseaussendung/OTS_20261022_OTS0163/kompass-energieunabhaengigkeit-jedes-jahr-fossile-importe-im-wert-von-1000-windraedern','published','2026-10-24T13:50:00.000Z','2026-10-24T13:44:37.308Z','Energieunabhängigkeit Österreich: Neuer Kompass','Energieunabhängigkeit Österreich: 59 % der Energie kommen aus dem Ausland, 10 Mrd. Euro jährlich für Öl und Gas. Alle Zahlen des Kompass im Überblick.','Energieunabhängigkeit Österreich','["Energieunabhängigkeit Österreich","Kompass Energieunabhängigkeit","Energieimporte Österreich","fossile Importe Kosten","Gasspeicher Füllstand Österreich","Oesterreichs Energie","Energieagentur","Erdgas Import Österreich","erneuerbarer Strom Österreich"]','Energieunabhängigkeit Österreich: Windräder, Stausee und Stromleitungen in einem Alpental','Austrian alpine valley in autumn with a row of modern wind turbines on a ridge, a hydropower reservoir dam below and high-voltage power lines crossing golden larch forests, soft late afternoon light, wide landscape, realistic, no text, no logos, no readable signs, no people','[{"q":"Wie viel Energie importiert Österreich?","a":"Laut Kompass Energieunabhängigkeit stammen rund 59 Prozent der in Österreich genutzten Energie aus dem Ausland, bei Erdöl 96 und bei Erdgas 93 Prozent."},{"q":"Wie viel kosten die fossilen Energieimporte?","a":"Im Schnitt der letzten zehn Jahre rund 10 Milliarden Euro netto pro Jahr, zuzüglich Kosten für Reserven und Krisenhilfen."},{"q":"Wo ist der Kompass Energieunabhängigkeit abrufbar?","a":"Die Plattform von Oesterreichs Energie und der Österreichischen Energieagentur ist frei unter oesterreichsenergie.at/kompass zugänglich."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
